29	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person_id"),
30	            money(rs.getBigDecimal("amount")), rs.getDate("claim_date").toLocalDate().toString(),
31	            rs.getString("note"), rs.getString("status"),
32	            rs.getString("claim_no"), dueOf(rs.getBigDecimal("settled_due")),
33	            rs.getString("opened_by"), rs.getBoolean("stated"), dueOf(rs.getBigDecimal("stated_due")),
34	            rs.getString("corrects"), rs.getDate("due_by").toLocalDate().toString(),
35	            rs.getBoolean("stated_na"),
36	            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
37	            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
38	            rs.getBoolean("late_entry"),
39	            rs.getDate("reminded") == null ? null : rs.getDate("reminded").toLocalDate().toString(),
40	            rs.getString("ref"), rs.getString("tags"), rs.getString("void_reason"), rs.getBoolean("waived"), rs.getInt("proofs_photo"), rs.getBoolean("held"));
