79	    public boolean personExists(String sheetId, long personId) {
80	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND id = ?",
81	                Integer.class, sheetId, personId);
82	        return known != null && known > 0;
83	    }
