101	    /** The sheet's claims, newest first. */
102	    public List<Claim> list(String sheetId) {
103	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC, id DESC", ROW, sheetId);
104	    }
