106	    /** A claim on the sheet; null when the sheet has no such claim. */
107	    public Claim find(String sheetId, long claimId) {
108	        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW,
109	                sheetId, claimId);
110	        return found.isEmpty() ? null : found.get(0);
111	    }
