113	    /** Move a claim to a status, only when it is now in one of {@code from}; false when it is not. */
114	    public boolean changeStatus(String sheetId, long claimId, List<String> from, String to) {
115	        String in = String.join(", ", from.stream().map(s -> "?").toList());
116	        List<Object> args = new ArrayList<>(List.of(to, claimId, sheetId));
117	        args.addAll(from);
118	        return kept(sheetId, claimId, jdbc.update("UPDATE claim SET status = ? WHERE id = ? AND sheet_id = ? AND status IN (" + in + ")",
119	                args.toArray()) > 0);
120	    }
