122	    /** Record the sheet's today as the claim's review day (it has just gone to REVIEW). */
123	    public void reviewDay(String sheetId, long claimId) {
124	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET review_day = ? WHERE id = ? AND sheet_id = ?",
125	                java.sql.Date.valueOf(settings.today(sheetId)), claimId, sheetId) > 0);
126	    }
