128	    /** Whether each REVIEW claim of the sheet is review-late (its review day plus the sheet's review SLA is before the
129	     *  sheet's today; none is while the SLA is blank), by claim id. */
130	    public Map<String, Boolean> reviewLate(String sheetId) {
131	        Map<String, Boolean> late = new LinkedHashMap<>();
132	        Integer sla = settings.reviewSla(sheetId);
133	        if (sla == null) return late;
134	        LocalDate today = settings.today(sheetId);
135	        jdbc.query("SELECT id, review_day FROM claim WHERE sheet_id = ? AND status = 'REVIEW' AND review_day IS NOT NULL",
136	                rs -> {
137	                    late.put(String.valueOf(rs.getLong("id")),
138	                            rs.getDate("review_day").toLocalDate().plusDays(sla).isBefore(today));
139	                }, sheetId);
140	        return late;
141	    }
