261	    /** The period a date falls in, as [id, name] (the earliest by from-date), or none. */
262	    private List<Object[]> periodOn(String sheetId, LocalDate date) {
263	        return jdbc.query("SELECT id, name FROM period WHERE sheet_id = ? AND from_date <= ?"
264	                + " AND to_date >= ? ORDER BY from_date LIMIT 1",
265	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("name") }, sheetId, Date.valueOf(date),
266	                Date.valueOf(date));
267	    }
