269	    /** Re-date an OPEN or PENDING claim (its due-by and statement binding stay as they are); false when the
270	     *  sheet has no such claim in those statuses. */
271	    public boolean redate(String sheetId, long claimId, LocalDate date) {
272	        return kept(sheetId, claimId, jdbc.update("UPDATE claim SET due_from = COALESCE(due_from, claim_date), claim_date = ? WHERE id = ? AND sheet_id = ?"
273	                + " AND status IN ('OPEN', 'PENDING')", Date.valueOf(date), claimId, sheetId) > 0);
274	    }
