282	    /** Record who last edited a claim. */
283	    public void editedBy(String sheetId, long claimId, String by) {
284	        jdbc.update("UPDATE claim SET edited_by = ? WHERE id = ? AND sheet_id = ?", by, claimId, sheetId);
