418	    /** The late charge on a claim's figure now (see {@link #dueNow}); zero when it is not overdue. */
419	    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
420	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
421	        if (!claim.open() || claim.deferred() || claim.waived()) return charge;
422	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
423	        if (found.isEmpty()) return charge;
424	        LocalDate today = found.get(0).toLocalDate();
425	        LocalDate dueBy = overdueFrom(sheetId, claim);
426	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
427	        if (periods == 0) return charge;
428	        RoundingMode rounding = rounding(sheetId, claim);
429	        for (long n = 1; n <= periods; n++) {
430	            BigDecimal pct = settings.latePct(sheetId, dueBy.plusDays(30 * n));
431	            if (pct == null || pct.signum() == 0) continue;
432	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
433	        }
434	        return charge;
435	    }
