534	    /** Move every claim of a person to another sheet, as the claims of the person {@code toPersonId} there: each keeps
535	     *  its status, dates, note, tags, settled due, status log, comments, lines and any figure a statement bound it to, and is listed
536	     *  in the same order; it loses its external reference, its lock and its settle batch. Each claim that had
537	     *  a number takes the other sheet's next one (as opening it there would give it), in the order the claims were
538	     *  opened (by the sheet's today when each was opened, then by the order they were added); a number one of them
539	     *  corrects or was split from follows it. The claims leave this sheet. */
540	    public void transferAll(String fromSheet, long personId, String toSheet, long toPersonId) {
541	        List<Long> ids = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
542	                Long.class, fromSheet, personId);
543	        Map<Long, Long> moved = new LinkedHashMap<>();
544	        for (Long claimId : ids) {
545	            GeneratedKeyHolder keys = new GeneratedKeyHolder();
546	            jdbc.update(c -> {
547	                PreparedStatement ps = c.prepareStatement("INSERT INTO claim (sheet_id, person_id, amount, claim_date, note,"
548	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
549	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na, waived, proofs_photo, held, due_from) SELECT ?, ?, amount, claim_date, note,"
550	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
551	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na, waived, proofs_photo, held, due_from FROM claim WHERE id = ? AND sheet_id = ?", new String[] { "id" });
552	                ps.setString(1, toSheet);
553	                ps.setLong(2, toPersonId);
554	                ps.setLong(3, claimId);
555	                ps.setString(4, fromSheet);
556	                return ps;
557	            }, keys);
558	            long arrived = keys.getKey().longValue();
559	            moved.put(claimId, arrived);
560	            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) SELECT ?, ?, status,"
561	                    + " by_user, on_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
562	                    toSheet, arrived, fromSheet, claimId);
563	            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text) SELECT ?, ?, by_user,"
564	                    + " on_date, text FROM claim_comment WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
565	                    toSheet, arrived, fromSheet, claimId);
566	            jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) SELECT ?, ?, label, qty, unit"
567	                    + " FROM claim_line WHERE sheet_id = ? AND claim_id = ? ORDER BY id", toSheet, arrived, fromSheet, claimId);
568	            used(toSheet, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, arrived));
569	        }
570	
571	        // Renumber on the other sheet, in the order the claims were opened.
572	        List<Object[]> numbered = jdbc.query("SELECT c.id, c.claim_no, c.due_by FROM claim c WHERE c.sheet_id = ?"
573	                + " AND c.person_id = ? AND c.claim_no IS NOT NULL ORDER BY (SELECT MIN(l.on_date) FROM claim_log l"
574	                + " WHERE l.sheet_id = c.sheet_id AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id",
575	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("claim_no"), rs.getDate("due_by").toLocalDate() },
576	                fromSheet, personId);
577	        boolean perPeriod = numbersPerPeriod(toSheet);
578	        Map<String, String> numbers = new LinkedHashMap<>();
579	        for (Object[] c : numbered) {
580	            long arrived = moved.get((Long) c[0]);
581	            numbers.put((String) c[1], perPeriod ? numberInPeriod(toSheet, arrived, (LocalDate) c[2]) : number(toSheet, arrived, (LocalDate) c[2]));
582	        }
583	        for (Long arrived : moved.values()) {
584	            Map<String, Object> was = jdbc.queryForMap("SELECT corrects, split_from FROM claim WHERE id = ?", arrived);
585	            String corrects = (String) was.get("corrects");
586	            String splitFrom = (String) was.get("split_from");
587	            jdbc.update("UPDATE claim SET corrects = ?, split_from = ? WHERE id = ?",
588	                    corrects == null ? null : numbers.getOrDefault(corrects, corrects),
589	                    splitFrom == null ? null : numbers.getOrDefault(splitFrom, splitFrom), arrived);
590	            history.claim(toSheet, arrived);
591	        }
592	
593	        for (Long claimId : ids) {
594	            jdbc.update("DELETE FROM claim_log WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
595	            jdbc.update("DELETE FROM claim_comment WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
596	            jdbc.update("DELETE FROM claim_line WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
597	            jdbc.update("DELETE FROM claim WHERE id = ? AND sheet_id = ?", claimId, fromSheet);
598	        }
599	    }
