678	    /** The due-by of a claim created now for a person with a date: the terms-th business day after the date (skipping
679	     *  Saturdays, Sundays and the sheet's holidays), for the terms in force on the day it is created (the sheet's today):
680	     *  the person's own terms in force that day, else the terms, in force that day, of the grade the person has that day,
681	     *  else the sheet's terms in force that day. */
682	    public LocalDate dueBy(String sheetId, long personId, LocalDate date) {
683	        LocalDate on = settings.today(sheetId);
684	        // the person's own terms in force that day: the latest dated ones on or before it, else those from the beginning
685	        List<Integer> mine = new java.util.ArrayList<>();
686	        jdbc.query("SELECT terms FROM person_terms WHERE sheet_id = ? AND person_id = ? AND from_date <= ?"
687	                + " ORDER BY from_date DESC LIMIT 1", rs -> {
688	                    mine.add((Integer) rs.getObject("terms", Integer.class));
689	                }, sheetId, personId, Date.valueOf(on));
690	        if (mine.isEmpty()) {
691	            mine.addAll(jdbc.queryForList("SELECT terms FROM person WHERE sheet_id = ? AND id = ?", Integer.class,
692	                    sheetId, personId));
693	        }
694	        if (!mine.isEmpty() && mine.get(0) != null) {
695	            return settings.businessDaysAfter(sheetId, date, mine.get(0));
696	        }
697	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId, personId,
698	                on.toString());
699	        return dueByOfGrade(sheetId, grade.isEmpty() ? null : grade.get(0), date);
700	    }
