734	    /** The business days (not a Saturday, Sunday or one of the holidays) after a date up to and including another. */
735	    private static int businessDaysBetween(java.util.Set<String> holidays, LocalDate from, LocalDate to) {
736	        int days = 0;
737	        for (LocalDate d = from.plusDays(1); !d.isAfter(to); d = d.plusDays(1)) {
738	            java.time.DayOfWeek day = d.getDayOfWeek();
739	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY && !holidays.contains(d.toString())) {
740	                days++;
741	            }
742	        }
743	        return days;
744	    }
