755	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
756	        LocalDate dueBy = dueBy(sheetId, personId, date);
757	        boolean late = lateEntry(sheetId, dueBy);
758	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
759	        jdbc.update(c -> {
760	            PreparedStatement ps = c.prepareStatement(
761	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, late_entry, ref, tags) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
762	                    new String[] { "id" });
763	            ps.setString(1, sheetId);
764	            ps.setLong(2, personId);
765	            ps.setBigDecimal(3, amount);
766	            ps.setDate(4, Date.valueOf(date));
767	            ps.setString(5, note);
768	            ps.setString(6, corrects);
769	            ps.setDate(7, Date.valueOf(dueBy));
770	            ps.setBoolean(8, late);
771	            ps.setString(9, ref);
772	            ps.setString(10, tags);
773	            return ps;
774	        }, keys);
775	        kept(sheetId, keys.getKey().longValue(), true);
776	        used(sheetId, tags);
777	        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects,
778	                dueBy.toString(), false, null, false, 0, null, late, null, ref, tags, null, false, 0, false);
