788	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from its last
789	     *  statement (live again); a new OPEN claim of the same person with the split-off amount, the same date and
790	     *  note and tags, opened by {@code by}, with its due-by fixed now and the original's number as split-from, is added
791	     *  (unnumbered until it is settled; a late entry when its due-by falls in a soft-closed period). The new claim's id, or null when the sheet has no such OPEN claim. */
792	    public Long split(String sheetId, Claim claim, BigDecimal amount, String by) {
793	        BigDecimal rest = new BigDecimal(claim.amount()).subtract(amount);
794	        if (jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE"
795	                + " WHERE id = ? AND sheet_id = ? AND status = 'OPEN'", rest, claim.id(), sheetId) == 0) {
796	            return null;
797	        }
798	        kept(sheetId, claim.id(), true);
799	        LocalDate date = LocalDate.parse(claim.date());
800	        LocalDate dueBy = dueBy(sheetId, claim.personId(), date);
801	        boolean late = lateEntry(sheetId, dueBy);
802	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
803	        jdbc.update(c -> {
804	            PreparedStatement ps = c.prepareStatement(
805	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, due_by, status, opened_by, split_from, late_entry, tags)"
806	                            + " VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?)",
807	                    new String[] { "id" });
808	            ps.setString(1, sheetId);
809	            ps.setLong(2, claim.personId());
810	            ps.setBigDecimal(3, amount);
811	            ps.setDate(4, Date.valueOf(date));
812	            ps.setString(5, claim.note());
813	            ps.setDate(6, Date.valueOf(dueBy));
814	            ps.setString(7, by);
815	            ps.setString(8, claim.number());
816	            ps.setBoolean(9, late);
817	            ps.setString(10, claim.tags());
818	            return ps;
819	        }, keys);
820	        kept(sheetId, keys.getKey().longValue(), true);
821	        return keys.getKey().longValue();
822	    }
