40	    /** Settle a claim as of a date (null: as it is now): its due is frozen as it stood at the end of that day (see
41	     *  {@link AsOfView}); a date after the sheet's today, or one before the claim existed, is refused. */
42	    static Claim settle(String id, long cid, String on, String by, AsOfView view, ClaimRepository repository,
43	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
44	        String raw = on == null ? "" : on.trim();
45	        LocalDate day = null;
46	        if (!raw.isEmpty()) {
47	            try {
48	                day = LocalDate.parse(raw);
49	            } catch (DateTimeParseException e) {
50	                throw new BadRequestException("the settle date must be yyyy-mm-dd");
51	            }
52	        }
53	        return apply(id, cid, "settle", null, by, false, null, day, view, repository, periods, settings, audit, rollup, watches);
54	    }
