    31	    public Person withRetirements(List<Retirement> retirements) {
    32	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements, flag, approver);
    33	    }
    34	
    35	    public Person withSnapshots(List<SnapshotLine> snapshots) {
    36	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements, flag, approver);
    37	    }
    38	
    39	    public Person withStatements(List<StatementLine> statements) {
    40	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements, flag, approver);
    41	    }
    42	
    43	    public boolean retired() {
    44	        return retiredFrom != null;
    45	    }
    46	
    47	    /** The holds that act on live totals on the sheet's today: none of their own holds (a hold acts only on pool
    48	     *  cuts), only, once their retirement date is reached (the sheet's today on or after it), a hold over every date. */
    49	    public List<Hold> liveHolds(String today) {
    50	        return claimedHolds(today);
    51	    }
    52	
    53	    /** The holds that keep their claims out of claimed on the sheet's today: none of their own holds (a hold
    54	     *  leaves claimed alone), only, once their retirement date is reached, a hold over every date. */
    55	    public List<Hold> claimedHolds(String today) {
    56	        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return List.of();
