49	                ROW, sheetId);
50	        Map<Long, Map<String, String>> totals = new HashMap<>();
51	        Map<Long, Map<String, String>> carried = new HashMap<>();
52	        jdbc.query("SELECT period_id, person_id, total, carried FROM period_person_total WHERE sheet_id = ? ORDER BY person_id",
53	                rs -> {
54	                    totals.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
55	                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("total").setScale(2).toPlainString());
56	                    carried.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
57	                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("carried").setScale(2).toPlainString());
58	                }, sheetId);
