60	        jdbc.query("SELECT period_id, person_id, amount FROM period_opening WHERE sheet_id = ? ORDER BY person_id",
61	                rs -> {
62	                    openings.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
63	                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("amount").setScale(2).toPlainString());
64	                }, sheetId);
