1	package net.officefloor.hq.app.period;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.time.YearMonth;
6	import java.util.Comparator;
7	import java.util.LinkedHashMap;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.regex.Pattern;
11	import net.officefloor.hq.app.Audit;
12	import net.officefloor.hq.app.BadRequestException;
13	import net.officefloor.hq.app.CurrentUser;
14	import net.officefloor.hq.app.claim.Claim;
15	import net.officefloor.hq.app.claim.ClaimRepository;
16	import net.officefloor.hq.app.person.Person;
17	import net.officefloor.hq.app.person.PersonRepository;
18	import net.officefloor.hq.app.settings.SettingsRepository;
19	import net.officefloor.plugin.variable.Out;
20	import net.officefloor.server.http.ServerHttpConnection;
21	import org.springframework.web.bind.annotation.PathVariable;
22	import org.springframework.web.bind.annotation.RequestBody;
23	
24	/** Roll a fiscal year (FY<yyyy>) over, by a steward only: make the next fiscal year's twelve monthly periods exactly
25	 *  as the fiscal year generator does, then add each person's open figure at the end of the old year's last period
26	 *  (the dues now of their claims that count whose due-by falls in a period of the old year — one starting within it —
27	 *  and that were OPEN or PENDING at that period's end) to their opening balance for the new year's first period
28	 *  (OPENING_SET, only for a figure above 0.00, and only when this rollover generated that period — a repeated
29	 *  rollover adds nothing again), and write ROLLOVER; then soft-close, as {@link SoftClosePeriod} would, every period
30	 *  of the old year still open (neither closed nor soft-closed), by from-date. A year that is not yyyy, or one with no periods,
31	 *  is refused. The rollover is kept as the sheet's last one, so {@link UndoRollover} can take it back. */
32	public class RolloverYear {
33	    private static final Pattern YEAR = Pattern.compile("\\d{4}");
34	
35	    public void rollover(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFyRequest request,
36	            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings,
37	            ClaimRepository claims, PersonRepository people, PeriodCloser closer, Audit audit, Out<GenerateResult> result)
38	            throws BadRequestException {
39	        String by = CurrentUser.require(connection);
40	        String id = sheetId == null ? "" : sheetId.trim();
41	        String year = request == null || request.year() == null ? "" : request.year().trim();
42	        if (!YEAR.matcher(year).matches()) {
43	            throw new BadRequestException("fiscal year must be a year (yyyy)");
44	        }
45	        if (!repository.lockSheet(id)) {
46	            throw new BadRequestException("no such sheet");
47	        }
48	        String role = settings.role(id, by);
49	        if (!SettingsRepository.STEWARD.equals(role)) {
50	            throw new BadRequestException("a " + role + " cannot roll a year over");
51	        }
52	        YearMonth start = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(id));
53	        List<Period> old = within(repository.list(id), start);
54	        if (old.isEmpty()) {
55	            throw new BadRequestException("FY" + year + " has no periods");
56	        }
57	        LocalDate end = old.stream().map(p -> LocalDate.parse(p.to())).max(Comparator.naturalOrder()).orElseThrow();
58	        String today = repository.today(id);
59	        Map<Long, String> statusesThen = claims.statusesOn(id, end);
60	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
61	        Map<Long, Person> byId = new LinkedHashMap<>();
62	        for (Person p : people.list(id)) {
63	            byId.put(p.id(), p);
64	            open.put(p.id(), BigDecimal.ZERO.setScale(2));
65	        }
66	        for (Claim c : claims.list(id)) {
67	            Person person = byId.get(c.personId());
68	            if (person == null) continue;
69	            String then = statusesThen.get(c.id());
70	            if (then == null || !(then.equals("OPEN") || then.equals("PENDING"))) continue;
71	            if (!c.countsAs(then, person.liveHolds(today), today)) continue;
72	            LocalDate on = LocalDate.parse(c.dueBy());
73	            boolean in = old.stream()
74	                    .anyMatch(q -> !on.isBefore(LocalDate.parse(q.from())) && !on.isAfter(LocalDate.parse(q.to())));
75	            if (!in) continue;
76	            BigDecimal now = claims.dueNow(id, c);
77	            if (now == null) continue;
78	            open.merge(c.personId(), now, BigDecimal::add);
79	        }
80	
81	        YearMonth next = start.plusMonths(12);
82	        java.util.Set<Long> before = new java.util.HashSet<>();
83	        repository.list(id).forEach(p -> before.add(p.id()));
84	        int made = GeneratePeriods.months(id, by, next, next.plusMonths(11), repository, audit);
85	        List<Period> after = repository.list(id);
86	        List<Long> generated = after.stream().map(Period::id).filter(p -> !before.contains(p)).toList();
87	        List<Object[]> openings = new java.util.ArrayList<>();
88	        Period first = within(after, next).stream().findFirst().orElse(null);
89	        if (first != null && generated.contains(first.id())) {
90	            for (Map.Entry<Long, BigDecimal> e : open.entrySet()) {
91	                if (e.getValue().signum() <= 0) continue;
92	                repository.addOpening(id, first.id(), e.getKey(), e.getValue());
93	                openings.add(new Object[] { first.id(), e.getKey(), e.getValue() });
94	                audit.record("OPENING_SET sheet=" + id + " by=" + by + " name=" + byId.get(e.getKey()).name()
95	                        + " period=" + first.name() + " amount=" + e.getValue().setScale(2).toPlainString());
96	            }
