    26	        try {
    27	            pid = Long.parseLong(personId == null ? "" : personId.trim());
    28	        } catch (NumberFormatException e) {
    29	            throw new BadRequestException("no such person");
    30	        }
    31	        Person into = people.find(id, pid);
