    10	/** Bind the opening balances paste box: each non-blank line is name,period,amount, the name and period not
    11	 *  blank and the amount two decimals, 0.00 or more. A paste with no lines, or a line with other fields, is refused. */
    12	public class ValidateOpenings {
    13	    public void validate(@RequestBody OpeningRequest request, Out<OpeningInput> openings) throws BadRequestException {
    14	        String text = request == null || request.text() == null ? "" : request.text();
    15	        List<OpeningLine> checked = new ArrayList<>();
    16	        int n = 0;
    17	        for (String raw : text.split("\r?\n", -1)) {
    18	            n++;
    19	            if (raw.isBlank()) {
    20	                continue;
    21	            }
    22	            String[] f = raw.split(",", -1);
    23	            if (f.length != 3) {
    24	                throw new BadRequestException("line " + n + ": a line is name,period,amount");
    25	            }
    26	            String name = f[0].trim();
    27	            String period = f[1].trim();
    28	            String amount = f[2].trim();
    29	            if (name.isEmpty()) {
    30	                throw new BadRequestException("line " + n + ": name is required");
    31	            }
    32	            if (period.isEmpty()) {
    33	                throw new BadRequestException("line " + n + ": period is required");
    34	            }
    35	            if (!amount.matches("\\d+\\.\\d{2}")) {
    36	                throw new BadRequestException("line " + n + ": amount must be 0.00 or more, with two decimals");
    37	            }
    38	            checked.add(new OpeningLine(n, name, period, new BigDecimal(amount)));
    39	        }
    40	        if (checked.isEmpty()) {
    41	            throw new BadRequestException("paste at least one opening balance");
    42	        }
    43	        openings.set(new OpeningInput(checked));
    44	    }
    45	}
