    23	/** Add or update a person per imported line, in order. A line whose name is a person's name or alias on the
    24	 *  sheet (ignoring case) updates that person as the person form would save them with their own name: the
    25	 *  grade is recorded from the sheet's today (none when it is unchanged), and their terms and contact are set
    26	 *  when the line gives them; written as PERSON_EDITED. Any other line adds a person as the person form does,
    27	 *  written as PERSON_ADDED. A line with a blank grade takes the sheet's default grade (A when it has none, or when it is retired). A grade retired on the sheet is refused, unless the line leaves a person on it as they are. One change: every line is checked first, so a refused line (or two lines naming
    28	 *  the same person) changes no one and writes no audit record. */
    29	public class ImportPeople {
    30	    public void importPeople(@PathVariable("sheetId") String sheetId, @Val ImportInput input,
    31	            ServerHttpConnection connection, PersonRepository repository, SheetRepository sheets, SettingsRepository settings, Audit audit,
    32	            Rollup rollup, Out<ImportResult> result) throws BadRequestException {
    33	        String by = CurrentUser.require(connection);
    34	        String id = sheetId == null ? "" : sheetId.trim();
    35	        if (!repository.sheetExists(id)) {
    36	            throw new BadRequestException("no such sheet");
    37	        }
    38	        String defaultGrade = settings.defaultGrade(id);
    39	        List<Person> matches = new ArrayList<>();
    40	        Set<Long> matched = new HashSet<>();
    41	        int n = 0;
    42	        for (PersonRequest person : input.people()) {
    43	            n++;
    44	            try {
    45	                Person current = repository.findByName(id, person.name());
    46	                if (current == null) {
    47	                    NewPerson.checkFree(repository, id, person);
    48	                } else {
    49	                    if (!matched.add(current.id())) {
    50	                        throw new BadRequestException(current.name() + " is given twice in the import");
    51	                    }
    52	                    if (!person.contact().isEmpty() && repository.contactTaken(id, person.contact(), current.id())) {
    53	                        throw new BadRequestException("contact is already in use");
    54	                    }
    55	                }
    56	                String grade = person.grade().isEmpty() ? defaultGrade : person.grade();
    57	                if (current == null || !grade.equals(current.grade())) {
    58	                    NewPerson.checkNotRetired(settings, id, grade);
    59	                }
    60	                matches.add(current);
    61	            } catch (BadRequestException e) {
    62	                throw new BadRequestException("line " + n + ": " + e.getMessage());
    63	            }
    64	        }
    65	        LocalDate today = sheets.today(id);
    66	        int added = 0;
    67	        int updated = 0;
    68	        for (int i = 0; i < input.people().size(); i++) {
    69	            PersonRequest person = input.people().get(i);
    70	            if (person.grade().isEmpty()) {
    71	                person = person.withGrade(defaultGrade);
    72	            }
    73	            Person current = matches.get(i);
    74	            if (current == null) {
    75	                NewPerson.add(repository, audit, rollup, id, by, person);
    76	                added++;
    77	            } else {
    78	                update(repository, audit, rollup, id, by, today, current, person);
    79	                updated++;
    80	            }
    81	        }
