    85	    private static void update(PersonRepository repository, Audit audit, Rollup rollup, String id, String by,
    86	            LocalDate today, Person current, PersonRequest person) throws BadRequestException {
    87	        Integer terms = person.terms().isEmpty() ? current.terms() : Integer.valueOf(person.terms());
    88	        String contact = person.contact().isEmpty() ? current.contact() : person.contact();
    89	        boolean regrade = !person.grade().equals(current.grade());
    90	        boolean reterm = !java.util.Objects.equals(terms, current.terms());
    91	        boolean recontact = !java.util.Objects.equals(contact, current.contact());
    92	        Rollup.Snapshot before = rollup.take(id);
    93	        if (!repository.update(id, current.id(), current.version(), current.name(), terms, contact)) {
    94	            throw new BadRequestException("someone else has saved " + current.name() + "; import again");
    95	        }
    96	        if (regrade) {
