9	/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
10	 *  claims left out once their retirement date is reached (a hold leaves none out) unless a statement binds them; a settled claim's frozen due, else the figure their last statement
11	 *  bound it to, else its live due, with its late charge while overdue),
12	 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
13	 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
14	 *  A shared claim counts its due less its holders' parts for its own person, and each holder's part (see sharePart: at the
15	 *  rate of their own grade on the claim's date, frozen once settled; 0.00 when they have no rate) for that holder.
16	 *  A due-total is at most the sheet's cap less their cut total (the cap in force on the date of their latest claim that
17	 *  counts; on the sheet's today when they have none), not below 0.00 ('n/a' is not capped). */
18	export function useDueTotals(sheetId: string): Map<number, string> {
19	  const totals = new Map<number, string>();
20	  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
21	  return totals;
22	}
