61	/** Each person's due-total, by person id, from these people, claims, rates and settings on this today (as
62	 *  useDueTotals shows them). */
63	export function dueTotalsOf(...args: Parameters<typeof dueFigures>): Map<number, string> {
64	  const totals = new Map<number, string>();
65	  for (const [id, f] of dueFigures(...args)) totals.set(id, f.total);
66	  return totals;
67	}
