   100	    private static String setting(Connection c, String sheetId, String key, LocalDate date) throws Exception {
   101	        try (PreparedStatement ps = c.prepareStatement("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = ?"
   102	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1")) {
   103	            ps.setString(1, sheetId);
   104	            ps.setString(2, key);
   105	            ps.setDate(3, Date.valueOf(date));
   106	            try (ResultSet rs = ps.executeQuery()) {
   107	                return rs.next() ? rs.getString(1) : null;
   108	            }
   109	        }
