  1	import { isOpen, useClaims } from '../claims/useClaims';
  2	import { claimDueNow } from '../overdue/useOverdue';
  3	import { gradeOn, usePeople } from '../people/usePeople';
  4	import { useSettings } from '../settings/useSettings';
  5	import { useSheetToday } from '../today/useSheetToday';
  6	import { hundredths, money, rateFor, useRates } from './useRates';
  7	
  8	/** A candidate rate's percent: 0.00 or more with up to two decimals (below 100000), as the rate form takes it. */
  9	const PCT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;
 10	
 11	/** What a candidate rate would change: how many open (OPEN or PENDING) claims of people on the grade (the grade
 12	 *  they had on the claim's date) would show a different due now were that rate the grade's on every date, and
 13	 *  the sum of new due minus current due. A claim a statement binds keeps its figure; a settled one is not open.
 14	 *  Returns a function computing it from the sheet as loaded; it throws on a bad percent. Saves nothing. */
 15	export function useRatePreview(sheetId: string): (grade: string, pct: string) => { count: number; diff: string } {
 16	  const people = usePeople(sheetId).data;
 17	  const claims = useClaims(sheetId).data;
 18	  const rates = useRates(sheetId).data;
 19	  const settings = useSettings(sheetId).data;
 20	  const today = useSheetToday(sheetId).data?.today;
 21	  return (grade, pct) => {
 22	    const candidate = pct.trim();
 23	    if (candidate === '') throw new Error('rate is required');
 24	    if (!PCT.test(candidate)) throw new Error('rate must be a percent of 0.00 or more with up to two decimals');
 25	    const asPct = money(hundredths(candidate.startsWith('.') ? `0${candidate}` : candidate));
 26	    let count = 0;
 27	    let diff = 0n;
 28	    for (const c of claims ?? []) {
 29	      if (!isOpen(c)) continue;
 30	      const p = (people ?? []).find((x) => x.id === c.personId);
 31	      const g = gradeOn(p, c.date);
 32	      if (g !== grade) continue;
 33	      const now = claimDueNow(c, claims, rateFor(rates, g, c.date, c.added), settings, today, g);
 34	      const next = claimDueNow(c, claims, asPct, settings, today, g);
 35	      if (now === next) continue;
 36	      count++;
 37	      diff += (next === 'n/a' ? 0n : hundredths(next)) - (now === 'n/a' ? 0n : hundredths(now));
 38	    }
 39	    return { count, diff: money(diff) };
 40	  };
 41	}
