1	package net.officefloor.hq.app.history;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.time.temporal.ChronoUnit;
7	import java.util.ArrayList;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.TreeMap;
11	import java.util.function.Function;
12	import net.officefloor.hq.app.claim.Claim;
13	import net.officefloor.hq.app.person.Hold;
14	import net.officefloor.hq.app.settings.SettingsRepository;
15	
16	/** A sheet as it stood at the end of a day: what the changes made while the sheet's today was on or
17	 *  before that day left (see {@link HistoryRepository#asOf}). The day stands in for the sheet's today in
18	 *  every figure, worked out by the same rules as the live ones in ClaimRepository: the grade and rate in
19	 *  force, the rounding, the floor, late charges, holds and retirements.
20	 *
21	 *  @param claims        each claim's values then, by claim id (a claim added later is absent)
22	 *  @param grades        each person's grades then, by person id, each by from-date (null: from the beginning of time)
23	 *  @param rates         each grade's rates then, by grade, each by from-date the rates set from it, in the order set
24	 *  @param settings      each dated setting's values then, by key, each by from-date
25	 *  @param policyDate    the policy date then (null: blank, the day itself)
26	 *  @param holds         each person's holds then, by person id
27	 *  @param retiredFrom   the date each person was retired from then, by person id (absent: not retired)
28	 *  @param correctedDate the date of a person's claim with a number (person id, number), for a correction's rounding
29	 *  @param added         each claim's added number, by claim id (see V83__forward_only_rate.sql)
30	 */
31	public record SheetAsOf(LocalDate day, Map<Long, Claim> claims, Map<Long, TreeMap<LocalDate, String>> grades,
32	        Map<String, TreeMap<LocalDate, List<Rate>>> rates, Map<String, TreeMap<LocalDate, String>> settings,
33	        LocalDate policyDate, Map<Long, List<Hold>> holds, Map<Long, String> retiredFrom,
34	        Function<Claim, String> correctedDate, Map<Long, Long> added) {
35	
36	    /** A rate then: its percent and to-date (null: with no end), and, when forward-only, the claim-added number it
37	     *  was set at (it applies only to claims with a higher one; null: to every claim). */
38	    public record Rate(BigDecimal pct, LocalDate to, Long after) {
39	    }
40	
41	    /** The minimum date, standing for "from the beginning of time" (a null from-date). */
42	    public static final LocalDate BEGINNING = LocalDate.of(1, 1, 1);
43	
44	    /** A person's claims then, newest first. */
45	    public List<Claim> claimsOf(long personId) {
46	        List<Claim> mine = new ArrayList<>();
47	        for (Claim c : claims.values()) {
48	            if (c.personId() == personId) mine.add(c);
49	        }
50	        mine.sort((a, b) -> Long.compare(b.id(), a.id()));
51	        return mine;
52	    }
53	
54	    /** The holds that acted on a person's live totals then: none of their own holds (a hold acts only on pool cuts),
55	     *  only, once their retirement date was reached, a hold over every date. */
56	    public List<Hold> liveHolds(long personId) {
57	        List<Hold> all = new ArrayList<>();
58	        String retired = retiredFrom.get(personId);
59	        if (retired != null && retired.compareTo(day.toString()) <= 0) all.add(new Hold(null, null));
60	        return all;
61	    }
62	
63	    private static <V> V latest(TreeMap<LocalDate, V> dated, LocalDate on) {
64	        if (dated == null) return null;
65	        Map.Entry<LocalDate, V> e = dated.floorEntry(on);
66	        return e == null ? null : e.getValue();
67	    }
68	
69	    /** The grade a person had then on a date. */
70	    public String gradeOn(long personId, LocalDate on) {
71	        return latest(grades.get(personId), on);
72	    }
73	
74	    /** The rate in force then for a person on a date, whatever claim it is for; null when there is none. */
75	    private Rate rateOn(long personId, LocalDate on) {
76	        return rateOn(personId, on, null);
77	    }
78	
79	    /** The rate that would apply then to a person on a date for a claim with an added number (null: any claim): of
80	     *  the latest from-date on or before it with a rate set that applies to the claim, the last such set; null when
81	     *  there is none. */
82	    private Rate rateOn(long personId, LocalDate on, Long claimAdded) {
83	        String grade = gradeOn(personId, on);
84	        TreeMap<LocalDate, List<Rate>> dated = grade == null ? null : rates.get(grade);
85	        if (dated == null) return null;
86	        for (Map.Entry<LocalDate, List<Rate>> e = dated.floorEntry(on); e != null; e = dated.lowerEntry(e.getKey())) {
87	            List<Rate> sets = e.getValue();
88	            for (int i = sets.size() - 1; i >= 0; i--) {
89	                Rate r = sets.get(i);
90	                if (claimAdded == null || r.after() == null || r.after() < claimAdded) return r;
91	            }
92	        }
93	        return null;
94	    }
95	
96	    /** A claim's added number; the highest there is when unknown. */
97	    private Long addedOf(Claim claim) {
98	        Long n = added.get(claim.id());
99	        return n == null ? Long.MAX_VALUE : n;
100	    }
101	
102	    /** A dated setting's value then on a date: a list holding the value (null when blank), empty when none was recorded. */
103	    private List<String> setting(String key, LocalDate on) {
104	        TreeMap<LocalDate, String> dated = settings.get(key);
105	        if (dated == null) return List.of();
106	        Map.Entry<LocalDate, String> e = dated.floorEntry(on);
107	        if (e == null) return List.of();
108	        List<String> found = new ArrayList<>();
109	        found.add(e.getValue());
110	        return found;
111	    }
112	
113	    /** The floor then on a date; 1.00 before any was recorded. */
114	    public BigDecimal floor(LocalDate on) {
115	        List<String> found = setting("floor", on);
116	        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
117	    }
118	
119	    /** The late percent then on a date; 0.00 before any was recorded. */
120	    public BigDecimal latePct(LocalDate on) {
121	        List<String> found = setting("late-pct", on);
122	        return found.isEmpty() || found.get(0) == null ? BigDecimal.ZERO.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
123	    }
124	
125	    /** The cap in force on the day; null when there was none. */
126	    public BigDecimal cap() {
127	        return cap(day);
128	    }
129	
130	    /** The cap in force on a date, as recorded by the day; null when there was none. */
131	    public BigDecimal cap(LocalDate on) {
132	        List<String> found = setting("cap", on);
133	        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
134	    }
135	
136	    /** A claim's rate figure then, not floored; null when no rate applied. */
137	    public BigDecimal due(Claim claim) {
138	        LocalDate date = LocalDate.parse(claim.date());
139	        Rate rate = rateOn(claim.personId(), date, addedOf(claim));
140	        if (rate == null || (rate.to() != null && rate.to().isBefore(date))) return null;
141	        return new BigDecimal(claim.amount()).multiply(rate.pct()).movePointLeft(2).setScale(2, rounding(claim));
142	    }
143	
144	    /** How a claim's figures rounded then: by the rounding mode in force on its date when there was one; else
145	     *  half up when dated before the policy date (blank: the day), else half to even; a correction by the date
146	     *  of the claim it corrects. */
147	    private RoundingMode rounding(Claim claim) {
148	        String date = claim.date();
149	        if (claim.corrects() != null) {
150	            String corrected = correctedDate.apply(claim);
151	            if (corrected != null) date = corrected;
152	        }
153	        List<String> mode = setting("rounding", LocalDate.parse(date));
154	        RoundingMode set = mode.isEmpty() ? null : SettingsRepository.roundingMode(mode.get(0));
155	        if (set != null) return set;
156	        LocalDate policy = policyDate != null ? policyDate : day;
157	        return LocalDate.parse(date).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
158	    }
159	
160	    /** A claim's figure then: its settled due, else the one a statement bound it to (none when bound to
161	     *  n/a), else its rate figure; null when it had none. */
162	    public BigDecimal figure(Claim claim) {
163	        if (claim.due() != null) return new BigDecimal(claim.due());
164	        if (claim.bound() && claim.statedNa()) return null;
165	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
166	        return due(claim);
167	    }
168	
169	    /** A claim's due then: its settled due, else the due a statement bound it to (as shown then), else its figure raised to at least the floor plus its late
170	     *  charges on the day on that floored figure (a correction has neither); null when it had no figure. */
171	    public BigDecimal dueNow(Claim claim) {
172	        if (claim.due() != null) return new BigDecimal(claim.due());
173	        if (claim.bound() && (claim.statedNa() || claim.statedDue() != null)) return figure(claim);
174	        BigDecimal figure = figure(claim);
175	        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
176	        BigDecimal floored = figure.max(floor(LocalDate.parse(claim.date())));
177	        return floored.add(lateCharge(claim, floored));
178	    }
179	
180	    /** The day a claim's overdue days counted from then: its due-by plus the grace days, then in force on its date,
181	     *  of the grade its person had on that date (its due-by when none). */
182	    public LocalDate overdueFrom(Claim claim) {
183	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
184	        LocalDate date = LocalDate.parse(claim.date());
185	        String grade = gradeOn(claim.personId(), date);
186	        if (grade == null) return dueBy;
187	        List<String> found = setting("grace-" + grade, date);
188	        return found.isEmpty() || found.get(0) == null ? dueBy : dueBy.plusDays(Integer.parseInt(found.get(0)));
189	    }
190	
191	    private BigDecimal lateCharge(Claim claim, BigDecimal figure) {
192	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
193	        if (!claim.open() || claim.deferred() || claim.waived()) return charge;
194	        LocalDate dueBy = overdueFrom(claim);
195	        long periods = dueBy.isBefore(day) ? ChronoUnit.DAYS.between(dueBy, day) / 30 : 0;
196	        RoundingMode rounding = rounding(claim);
197	        for (long n = 1; n <= periods; n++) {
198	            BigDecimal pct = latePct(dueBy.plusDays(30 * n));
199	            if (pct.signum() == 0) continue;
200	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
201	        }
202	        return charge;
203	    }
