89	    /** Whether the person was on the sheet at the end of a day: added while the sheet's today was on or before it. */
90	    public boolean existed(String sheetId, long personId, LocalDate day) {
91	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND id = ? AND added_on <= ?",
92	                Integer.class, sheetId, personId, Date.valueOf(day));
93	        return n != null && n > 0;
94	    }
