 34	/** Shows a value as the signed-in user's locale does (figureIn); a value that is not text is shown as it is. */
 35	export function useFigure(): <T>(value: T) => T | string {
 36	  const locale = useLocale();
 37	  return <T,>(value: T) => (typeof value === 'string' ? figureIn(locale, value) : value);
 38	}
