439	/** Each person's score, by person id: their settled figures (the sum of the figures of their counting SETTLED
440	 *  claims that correct nothing) divided by 100, minus 5 for every overdue claim of theirs that counts, rounded half to even to a
441	 *  whole number. Worked in whole numbers, so exact. Missing until their figures are loaded. */
442	export function useScores(sheetId: string): Map<number, bigint> {
443	  const scored = useScoreSettled(sheetId);
444	  const overdue = useOverdue(sheetId);
445	  const scores = new Map<number, bigint>();
446	  for (const [id, s] of scored) {
447	    const o = overdue.get(id);
448	    if (o === undefined) continue;
449	    scores.set(id, halfEven(hundredths(s), 10_000n) - 5n * BigInt(o.count));
450	  }
451	  return scores;
452	}
453	
454	/** n / d (d > 0) rounded half to even to a whole number. */
455	function halfEven(n: bigint, d: bigint): bigint {
456	  let q = n / d;
457	  let r = n % d;
458	  if (r < 0n) { q -= 1n; r += d; }
459	  if (2n * r > d || (2n * r === d && q % 2n !== 0n)) q += 1n;
460	  return q;
461	}

