408	    /** A sheet's ancestors, nearest first: its parent, the parent's parent and so on, stopping at a sheet seen
409	     *  before. */
410	    public List<String> lineage(String sheetId) {
411	        List<String> found = new java.util.ArrayList<>();
412	        for (String at = parent(sheetId); at != null && !found.contains(at) && !at.equals(sheetId); at = parent(at)) {
413	            found.add(at);
414	        }
415	        return found;
416	    }
