418	    /** A sheet's descendants: the sheets naming it as their parent, their children and so on, nearer first,
419	     *  each once and never the sheet itself. */
420	    public List<String> descendants(String sheetId) {
421	        List<String> found = new java.util.ArrayList<>();
422	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
423	        while (!pending.isEmpty()) {
424	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", String.class, pending.poll())) {
425	                if (child.equals(sheetId) || found.contains(child)) continue;
426	                found.add(child);
427	                pending.add(child);
428	            }
429	        }
430	        return found;
431	    }
