433	    /** The sheets whose rates a sheet's grade falls back to, nearest first: its ancestors up to three levels up,
434	     *  then (when it was cloned) the sheet it was cloned from and that one's own fallbacks (its ancestors, then its
435	     *  source, and so on); each once and never the sheet itself. */
436	    public List<String> rateAncestors(String sheetId) {
437	        List<String> found = new java.util.ArrayList<>();
438	        java.util.Set<String> sources = new java.util.HashSet<>();
439	        for (String at = sheetId; at != null && sources.add(at); at = clonedFrom(at)) {
440	            if (!at.equals(sheetId) && !found.contains(at)) found.add(at);
441	            List<String> up = lineage(at);
442	            for (String a : up.size() > 3 ? up.subList(0, 3) : up) {
443	                if (!a.equals(sheetId) && !found.contains(a)) found.add(a);
444	            }
445	        }
446	        return found;
447	    }
