 15	/** One sheet's figures: its people (retired included), each as the names they go by (their name and aliases, as
 16	 *  names are compared: ignoring case), joined by '\t' within a person and '\n' between people; each person's
 17	 *  due-total and overdue-total (as its header works them out), and settled-total, open-total and cut total (as its
 18	 *  row shows them), comma separated; and, as its summary shows them, per grade the due-totals of the people on it (retired left
 19	 *  out) added up, and per status how many claims have it. While the screen shows a date, each sheet is read as it stood at the end of that day, with that
 20	 *  date as its today. */
 21	type Figures = { people: string; due: string; overdue: string; settled: string; open: string; cut: string; grades: string; statuses: string };
 22	
 23	/** How names are compared: ignoring case (and surrounding spaces). */
 24	const nameKey = (name: string) => name.trim().toLowerCase();
 25	
 26	/** The sheet's people (retired included), each as the names they go by (see `Figures.people`), as of the screen's
 27	 *  as-of date when one is set. */
 28	function usePeopleNames(sheetId: string) {
 29	  return useQuery({
 30	    queryKey: [...peopleKey(sheetId), 'names'],
 31	    queryFn: async () => {
 32	      const got = await getJson<{ people: Person[]; aliases?: Alias[] }>(
 33	        `/api/sheets/${encodeURIComponent(sheetId)}/people`);
 34	      return got.people.map((p) => [p.name, ...(got.aliases ?? []).filter((a) => a.personId === p.id).map((a) => a.alias)]
 35	        .map(nameKey).join('\t')).join('\n');
 36	    },
 37	  });
 38	}
 39	
 40	/** How many people there are over all sheets' people (see `Figures.people`): people who share a name or alias are
 41	 *  one person (and so, in turn, are those who share one with either). */
 42	function countPeople(sheets: string[]): number {
 43	  const people = sheets.flatMap((s) => (s === '' ? [] : s.split('\n'))).map((p) => p.split('\t'));
 44	  const parent = people.map((_, i) => i);
 45	  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
 46	  const byName = new Map<string, number>();
 47	  people.forEach((names, i) => {
 48	    for (const n of names) {
 49	      const at = byName.get(n);
 50	      if (at === undefined) byName.set(n, i);
 51	      else parent[root(at)] = root(i);
 52	    }
 53	  });
 54	  return people.filter((_, i) => root(i) === i).length;
 55	}
