240	/** Whether a plan date (yyyy-mm-dd) falls in one of the plan's pauses: on or after the day it was paused and
241	 *  before the day it was resumed. Such a date is skipped. */
242	function skipped(plan: Plan, on: string): boolean {
243	  return (plan.pauses ?? []).some((p) => on >= p.from && (p.to == null || on < p.to));
244	}
