  6	/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote
  7	 *  or a line break. */
  8	function csvValue(v: string): string {
  9	  return /[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
