 12	/** Download these lines as a CSV file of this name, each line ending with a line feed. */
 13	export function downloadCsv(lines: string[][], filename: string) {
 14	  const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
 15	  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
 16	  const a = document.createElement('a');
 17	  a.href = url;
 18	  a.download = filename;
 19	  document.body.appendChild(a);
 20	  a.click();
 21	  a.remove();
 22	  setTimeout(() => URL.revokeObjectURL(url), 1000);
 23	}
