252	// The people ticked for a bulk grade, per sheet. Shared by every person's row (which ticks them) and the
253	// bulk grade bar (which acts on them), so it lives outside any one component.
254	const selected = new Map<string, ReadonlySet<number>>();
255	const listeners = new Set<() => void>();
256	const NONE: ReadonlySet<number> = new Set();
