268	/** The sheet's selected person ids, a way to tick or untick one, and a way to clear them all. */
269	export function usePersonSelection(sheetId: string) {
270	  const ids = useSyncExternalStore(subscribe, () => selected.get(sheetId) ?? NONE);
271	  const toggle = (id: number, on: boolean) => {
272	    const next = new Set(selected.get(sheetId) ?? NONE);
273	    if (on) next.add(id);
274	    else next.delete(id);
275	    set(sheetId, next);
276	  };
277	  const clear = () => set(sheetId, NONE);
278	  return { ids, toggle, clear };
279	}
