366	/** Shares (in hundredths) for patrons in the order they were named: 100.00 split equally, each share rounded
367	 *  half to even to two decimals, the remainder (100.00 less the shares added up) given to the first-named. */
368	function shares(count: number): bigint[] {
369	  if (count === 0) return [];
370	  const n = BigInt(count);
371	  let each = 10000n / n;
372	  const rest = 10000n % n;
373	  if (rest * 2n > n || (rest * 2n === n && each % 2n === 1n)) each += 1n;
374	  const all = Array.from({ length: count }, () => each);
375	  all[0] += 10000n - each * n;
376	  return all;
377	}
