395	    .map((x) => people.data?.find((p) => p.id === x.patronId))
396	    .filter((p): p is Person => p !== undefined);
397	  const split = shares(named.length);
398	  const labels = named
399	    .map((p, i) => ({ name: p.name, shown: shownName(p), share: split[i] }))
400	    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
401	    .map((x) => `${x.shown} ${money(x.share)}`);
402	  const from = today === undefined ? undefined : windowStart(today);
403	  const figure = (patronId: number) => hundredths(sumDues((claims.data ?? [])
