409	  const size = signed < 0n ? -signed : signed;
410	  let cents = size / 10000n;
411	  const rest = size % 10000n;
412	  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
413	  const backing = money(signed < 0n ? -cents : cents);
