312	    /** A holder's part of a claim (see {@link ClaimShare}): a settled claim's part as frozen, its frozen due times the
313	     *  share divided by 100 (see {@link ClaimShare#part}); else the claim's amount times the share divided by 100, times
314	     *  the rate of the holder's own grade in force on the claim's date divided by 100, rounded by the claim's rounding
315	     *  (see {@link #rounding}); null when the holder's grade has no rate then (a part of 0.00). */
316	    public BigDecimal part(String sheetId, Claim claim, ClaimShare share) {
317	        if (claim.due() != null) return ClaimShare.part(new BigDecimal(claim.due()), share.share());
318	        BigDecimal pct = rateInForce(sheetId, share.personId(), LocalDate.parse(claim.date()), added(sheetId, claim.id()));
319	        if (pct == null) return null;
320	        return new BigDecimal(claim.amount()).multiply(new BigDecimal(share.share())).multiply(pct).movePointLeft(4)
321	                .setScale(2, rounding(sheetId, claim));
322	    }
