335	    /** How a claim's live figures round: by the sheet's rounding mode in force on the claim's date (half-up or
336	     *  half-even) when there is one; else half up when the claim is dated before the sheet's policy date
337	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
338	     *  claim it corrects (its person's claim with that number), not its own. */
339	    public RoundingMode rounding(String sheetId, Claim claim) {
340	        String date = claim.date();
341	        if (claim.corrects() != null) {
342	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
343	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
344	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
345	        }
346	        List<String> mode = jdbc.queryForList("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = 'rounding'"
347	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, Date.valueOf(LocalDate.parse(date)));
348	        RoundingMode set = mode.isEmpty() ? null : SettingsRepository.roundingMode(mode.get(0));
349	        if (set != null) return set;
350	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
351	                Date.class, sheetId);
352	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
353	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
354	                : RoundingMode.HALF_EVEN;
355	    }
356	
357	    /** A claim's figure now: the due fixed when it was settled, else the due as shown its last statement bound
358	     *  it to (floor and late charge included; none when it bound it to n/a), else its live rate figure (not floored);
359	     *  null when it has none. */
360	    public BigDecimal figure(String sheetId, Claim claim) {
361	        if (claim.due() != null) return new BigDecimal(claim.due());
362	        if (claim.bound() && claim.statedNa()) return null;
363	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
364	        return due(sheetId, claim);
365	    }
366	
367	    /** A claim's due now: a settled claim's frozen due; else its floored figure (the greater of the sheet's floor in
368	     *  force on the claim's date and its live rate figure) plus, while it
369	     *  is overdue (OPEN or PENDING and its due-by — fixed when it was created — plus its grade's grace days before the
370	     *  sheet's today), for every full 30 days it is overdue, the sheet's late percent in force on that boundary date (the
371	     *  due-by plus the grace plus 30, 60,
372	     *  90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded to two decimals by the claim's rounding, the charges added up (a
373	     *  boundary whose percent is 0.00 adds nothing). A claim bound by a statement shows the due its last statement
374	     *  bound it to, as it was shown then (late charge and floor included): its charge no longer follows the sheet's
375	     *  today until the statement is cancelled. A correction (a negative amount) has no floor and no late charge,
376	     *  nor does a deferred claim have a charge (it is not overdue). Null when it has no figure. */
377	    public BigDecimal dueNow(String sheetId, Claim claim) {
378	        if (claim.due() != null) return new BigDecimal(claim.due());
379	        if (claim.bound() && (claim.statedNa() || claim.statedDue() != null)) return figure(sheetId, claim);
380	        BigDecimal figure = figure(sheetId, claim);
381	        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
382	        BigDecimal floored = figure.max(settings.floor(sheetId, LocalDate.parse(claim.date())));
383	        return floored.add(lateCharge(sheetId, claim, floored));
384	    }
385	
386	    /** The day a claim's overdue days are counted from: its due-by plus the grace days, in force on the claim's date,
387	     *  of the grade its person had on that date (its due-by when that grade has no grace then). The claim is overdue
388	     *  while open, not deferred, and this day is before the sheet's today; its 30-day late charge boundaries count
389	     *  from it. */
390	    public LocalDate overdueFrom(String sheetId, Claim claim) {
391	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
392	        String grade = gradeOn(sheetId, claim);
393	        if (grade == null) return dueBy;
394	        Integer grace = settings.gradeGrace(sheetId, grade, LocalDate.parse(claim.date()));
395	        return grace == null ? dueBy : dueBy.plusDays(grace);
396	    }
