480	     *  the rates that apply to it (see {@link #CLAIM_RATE_FOR}; {@code added} is its added number, null for all). */
481	    public BigDecimal rateInForce(String sheetId, long personId, LocalDate on, Long added) {
482	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId,
483	                personId, on.toString());
