485	        List<String> chain = new ArrayList<>();
486	        chain.add(sheetId);
487	        chain.addAll(settings.rateAncestors(sheetId));
488	        for (String at : chain) {
489	            List<BigDecimal> pct = added == null
490	                    ? jdbc.queryForList("SELECT a.pct FROM " + RATE_FOR + " a"
491	                            + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
492	                            at, grade.get(0), on.toString(), on.toString())
493	                    : jdbc.queryForList("SELECT a.pct FROM " + CLAIM_RATE_FOR + " a"
494	                            + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
495	                            at, grade.get(0), on.toString(), added, on.toString());
496	            if (!pct.isEmpty()) return pct.get(0);
497	        }
498	        return null;
499	    }
