329	   329	  const [counter, setCounter] = useState(0);
330	   330	  const [onLines] = useState(() => (id: string, lines: string[]) =>
331	   331	    setFound((f) => ({ ...f, lines: { ...f.lines, [id]: lines } })));
332	   332	
333	   333	  const search = async () => {
334	   334	    const n = counter + 1;
335	   335	    setCounter(n);
336	   336	    setRun(null);
