358	   358	      <span data-testid="search-count">{done ? lines.length : ''}</span>
359	   359	      {run?.sheets.map((id) => (
360	   360	        <SheetMatches key={`${run.n}-${id}`} sheetId={id} text={run.text} onLines={onLines} />
361	   361	      ))}
