    const ownDues = own.map((c) => {
      const d = dueOf.get(c.id)!;
      if (d === 'n/a' || c.shares.length === 0) return d;
      return money(hundredths(d) - c.shares.reduce((sum, s) => {
        const part = partOf(c, s);
        return sum + (part === 'n/a' ? 0n : hundredths(part));
